import { MeshStandardNodeMaterial } from 'three/webgpu';
import { texture, uv } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // Root container
  const root = new Group();

  // Geometry (tessellated plane)
  const geometry = new PlaneGeometry(1, 1, 64, 64);

  // Placeholder material (will be updated when textures load)
  const material = new MeshStandardNodeMaterial();
  material.colorNode = texture(uv()); // temporary white
  material.displacementNode = texture(uv()); // temporary flat

  const mesh = new Mesh(geometry, material);
  root.add(mesh);

  // Load textures asynchronously
  const texPromise = ctx.textureLoader.loadTexture(config.imageUrl);
  const depthPromise = ctx.textureLoader.loadTexture(config.depthMapUrl);

  texPromise.then((tex) => {
    material.mapNode = texture(tex);
    material.needsUpdate = true;
  });

  depthPromise.then((depthTex) => {
    material.displacementNode = texture(depthTex);
    material.displacementScale = 0.2;
    material.needsUpdate = true;
  });

  // Apply cinematic primitives
  const primitives = [];

  const parallax = ctx.primitives['parallax-scroll'](root, {
    intensity: 0.4,
  });
  primitives.push(parallax);

  const depthRotate = ctx.primitives['depth-rotate'](root, {
    maxDeg: 8,
  });
  primitives.push(depthRotate);

  // Event handlers
  root.userData.handlers = {};

  root.userData.handlers.hover = () => {
    // rise-in like hover (subtle upward motion)
    const tl = gsap.timeline();
    tl.to(mesh.position, {
      y: mesh.position.y + 0.15,
      duration: 0.7,
      ease: 'power3.out',
    });
    // store for cleanup
    root.userData._hoverTimeline = tl;
  };

  root.userData.handlers.click = () => {
    ctx.emit('hub-pricing.select', {});
  };

  // Cleanup routine
  root.userData.cleanup = () => {
    // dispose geometry & material
    geometry.dispose();
    material.dispose();

    // kill hover timeline if exists
    if (root.userData._hoverTimeline) {
      root.userData._hoverTimeline.kill();
    }

    // cleanup primitives
    primitives.forEach((p) => {
      if (p.timeline) p.timeline.kill();
      if (p.cleanup) p.cleanup();
    });
  };

  return root;
}
